export const C4_STAGES=['idle','c4_crossing','c4_chains','c4_report','c4_braziers','c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'];
const objectives={c4_crossing:'Поговорите с паромщиком Куртом в Чёрных заводях',c4_chains:'Разбейте три заколдованные цепи на островах',c4_report:'Вернитесь к Курту',c4_braziers:'Погасите три жаровни в Пепельном аббатстве',c4_abbess:'Победите Слепую Матерь',c4_prisoner:'Подберите лунную печать и освободите Эльзу',c4_egg:'Решите судьбу осквернённого яйца',c4_dragon:'Победите Пеплокрыла в его гнезде',c4_return:'Подберите сердце пепла и вернитесь к Воссу',c4_done:'Глава 4 завершена · восточная переправа свободна'};
export function chapterFourQuest({p,slots,world,legacy,show,close,sync,sound,reward,shop,cloakMenu,lootMenu,storageMenu,stored=()=>[],bags=()=>[],voice=()=>{},onContinue=null}){
 let state={stage:'idle',chains:[],braziers:[],egg:null,side:'idle'};const active=()=>p.stage==='chapter_four',owned=id=>countItem(slots,id)+countItem(stored(),id)+bags().reduce((n,b)=>n+(b.items||[]).filter(i=>i.id===id).reduce((v,i)=>v+i.count,0),0);
 const errand=orderErrand({p,slots,show,close,sync,sound,reward,shop,stored,bags,changed:()=>{flags();sync()}});
 function flags(){world?.setStory({orderErrand:p.orderErrand,parcelMask:p.orderParcelMask,lodging:p.rewards.includes('c3-scout'),chapterFour:true,fourStage:state.stage,chains:[...state.chains],braziers:[...state.braziers],egg:state.egg,prisonerReady:['c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage),abbessActive:['c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage),dragonActive:['c4_dragon','c4_return','c4_done'].includes(state.stage),workers:[0,1,2],powder:[0,1,2],side:'reported'})}
 function advance(stage){state.stage=stage;flags();sync();sound()}
 function begin(){p.stage='chapter_four';if(state.stage==='idle')state.stage='c4_crossing';flags();sync();sound();show('Глава 4. Пепел над водой',"Восс: «Барон больше не мешает, но переправа всё ещё стоит. Люди не могут привезти еду, а с востока приходят вести о драконе. Найди паромщика Курта. Он должен знать, что случилось. Выйдешь восточными воротами, за мастерскими».");return true}
 function tick(){if(!active())return;if(state.stage==='c4_chains'&&state.chains.length===3)advance('c4_report');if(state.stage==='c4_braziers'&&state.braziers.length===3){advance('c4_abbess');show('Погасшие жаровни','Из часовни доносится женский голос: «Огонь не погас. Он лишь остался без пищи». За алтарём поднимается Слепая Матерь. Её защиту больше не питают жаровни.')}
 if(state.stage==='c4_abbess'&&world.findActor('abbess')?.hp===0)advance('c4_prisoner');if(state.stage==='c4_dragon'&&world.findActor('ashwing')?.hp===0)advance('c4_return');if(['c4_prisoner','c4_egg','c4_dragon','c4_return'].includes(state.stage)&&!owned('moon_seal'))world.ensureQuestDrop('moon_seal','abbess');if(state.stage==='c4_return'&&!owned('ash_heart'))world.ensureQuestDrop('ash_heart','ashwing');flags();world.updateUI(marker)}
 function marker(id){const extra=errand.marker(id);if(extra)return extra;if(!active())return null;if(id==='c3-commander'&&state.stage==='c4_return')return {symbol:'?'};if(id==='c3-ferryman'&&['c4_crossing','c4_report'].includes(state.stage))return {symbol:state.stage==='c4_report'?'?':'!'};if(id==='c3-c4-prisoner'&&state.stage==='c4_prisoner')return {symbol:'?'};if(id==='c3-tracker')return state.side==='idle'?{symbol:'!',optional:true}:state.side==='collect'?{symbol:countItem(slots,'moon_herb')>=4?'?':'!',optional:true}:null;return null}
 function talk(n){const say=npcDialogue(p,n,show,close);
 if(n.id==='c3-commander'){if(state.stage==='c4_done'&&onContinue)return say(n.name,'Мы собираемся к Чёрной короне. Прямую дорогу перекрыли, а проход под горой держат дварфы Рудного Брода. Им нужна помощь, нам — дорога. Возьмёшься договориться?',[["Отправиться к Рудному Броду",onContinue],['Подготовлюсь',close]]);if(state.stage==='c4_return'){const copy=slots.map(i=>i?{...i}:null),id='ring_'+(state.egg==='purify'?'dawn_':'cinder_')+p.classId;if(!removeItem(copy,'ash_heart')||!removeItem(copy,'moon_seal'))return say(n.name,'Принеси лунную печать Матери и сердце пепла Пеплокрыла. Если оставил в сундуке — забери.');if(!addItem(copy,id))return say(n.name,'Освободи ячейку для награды.');slots.splice(0,slots.length,...copy);reward(p,'c4-final','quest',2400);advance('c4_done');say(n.name,"Курт снова возит людей, Эльза вернулась. Хорошая работа. Вот кольцо и обещанная плата.\n\nЗнак на печати я узнал: так метят имущество двора Дракулы. Значит, Матерь работала на него, а барон охранял дорогу. Дальше стоит крепость Чёрная корона. Туда пойдём, когда соберём людей и припасы. В этот раз без обоза не обойтись.");return}return say(n.name,state.stage==='c4_done'?'К востоку снова уходят обозы. Дозор будет держать дорогу. До Чёрной короны одному не добраться — сперва соберём людей.':'Курт ждёт у переправы. Восточные ворота стоят у края двора, за мастерскими.')}
 if(n.id==='c3-ferryman'){if(state.stage==='c4_crossing'){advance('c4_chains');return say(n.name,"Паром не ходит. Три заколдованные цепи держат его у берега, возле каждой сидят ведьмы. Разобьёшь цепи — я смогу перевезти людей.\n\nВсем здесь заправляет ведьма из аббатства, её зовут Матерью. Требовала отдавать ей каждого десятого пассажира, иначе обещала натравить дракона. Сестра отказалась. Теперь Эльзу держат у неё. Помоги запустить паром, а потом подумаем, как её вытащить.")}
 if(state.stage==='c4_report'){reward(p,'c4-chains','quest',1300);advance('c4_braziers');return say(n.name,"Паром свободен! Сейчас проверю канат и начну перевозить людей. Спасибо тебе.\n\nЭльза всё ещё в аббатстве. Один из беглецов видел три жаровни: пока они горят, Матерь почти невозможно ранить. Погаси их, потом ищи сестру. К аббатству ведут северные мостки. Вернёшь Эльзу — обещаю не брать с тебя за проезд. Даже за багаж.")}
 return say(n.name,state.stage==='c4_done'?"Первый обоз уже переправили. Эльза велит чинить крышу, а я всё улыбаюсь. Пусть ругает. Главное, что вернулась.":'Паром готов. Я вывезу людей, а ты возвращай Эльзу. На мостках держись середины — под водой нет дна, на которое можно встать.',[['Припасы для дороги',()=>shop('order_supplies')],['До встречи',close]])}
 if(n.id==='c3-tracker'){if(state.side==='idle')return say(n.name,"Ведьма меня прокляла. В голове свистит без остановки — думала, гарпии, но те хоть иногда спят. Нужно четыре пучка лунной травы. Она растёт в болотах, ведьмы таскают её с собой, иногда попадается и у утопцев. Соберёшь? Я дам оберег.",[['Соберу травы',()=>{state.side='collect';sync();sound();close()}],['Не сейчас',close]]);if(state.side==='collect'&&countItem(slots,'moon_herb')>=4)return say(n.name,"Трава при тебе? Давай попробуем. Если не поможет, хотя бы буду пахнуть получше.",[['Отдать четыре пучка',()=>{const copy=slots.map(i=>i?{...i}:null);removeItem(copy,'moon_herb',4);if(!addItem(copy,'ring_reed'))return say(n.name,'Освободи ячейку для оберега.');slots.splice(0,slots.length,...copy);state.side='done';reward(p,'c4-reyna','quest',800);sync();sound();say(n.name,"Свист прошёл. Наконец-то! Держи оберег, мы договорились. А я пойду посплю, пока никто не вспомнил, что я проводник.")}],['Позже',close]]);return say(n.name,state.side==='done'?"Соберу людей и поведу к Курту. Теперь хотя бы услышу, если кто-нибудь отстанет.":'Ищи лунную траву у болотных ведьм и утопцев. Четырёх пучков хватит.')}
 if(n.id==='c3-c4-prisoner'){if(state.stage==='c4_prisoner'){if(!countItem(slots,'moon_seal'))return say(n.name,'Печать Матери управляет путами. Подбери её у алтаря — без неё цепи не отпустят.');reward(p,'c4-elsa','quest',1200);advance('c4_egg');return say(n.name,"Курт тебя прислал? Так и знала, что не оставит. Я сама доберусь до парома, только сначала послушай.\n\nНа алтаре драконье яйцо. Матерь связала его с Пеплокрылом и мучила детёныша, чтобы взрослый дракон прилетал сюда. Её печать может снять заклятие. Можно и разбить яйцо — защита дракона ослабнет, но он разозлится и позовёт выводок. Реши сам. Я бы сначала попробовала печать.")}
 return say(n.name,'Я пойду к брату. Ты уже сделал достаточно, чтобы я могла выбраться сама.')}
 if(n.id==='c3-c4-pilgrim')return say(n.name,"Думал, в аббатстве накормят и дадут ночлег. Накормили, а потом заперли. Если ещё раз пойду в паломники — начну с трактира.");
 if(n.id==='c3-armorer')return say(n.name,"Из драконьей чешуи и лунной травы сделаю оружие покрепче. Нужно 6 чешуек, 4 пучка и 65 золотых. Можешь сначала посмотреть свойства — кошелёк останется цел.\n\n"+comparison(p.classId+'_ash',slots,p),[['Изготовить оружие',()=>{const copy=slots.map(i=>i?{...i}:null);if(countItem(copy,'dragon_scale')<6||countItem(copy,'moon_herb')<4||(p.gold||0)<65)return say(n.name,'Нужно6чешуек дракона,4лунные травы и65золота.');removeItem(copy,'dragon_scale',6);removeItem(copy,'moon_herb',4);if(!addItem(copy,p.classId+'_ash'))return say(n.name,'Освободи ячейку для оружия.');slots.splice(0,slots.length,...copy);p.gold-=65;sync();say(n.name,"Готово, оружие в сумке. Горячее, руками за наконечник не хватай. Это совет кузнеца, бесплатно.")}],['Сшить плащ чёрных заводей',()=>cloakMenu(true,()=>talk(n))],['Открыть лавку',()=>shop('order_smith')],['До встречи',close]]);
 if(n.id==='c3-quartermaster'&&errand.talk(n.name))return;if(n.id==='c3-quartermaster'||n.id==='c3-doctor')return say(n.name,'Собираешься в заводи? Пополни припасы до выхода.',[['Открыть лавку',()=>shop('order_supplies')],['До встречи',close]]);
 return orderChat(n,show,close)
 }
 function interact(){if(!active()||!world.inside)return false;const a=world.action();if(!a)return false;
 if(a.type==='npc'){voice(a.npc.woman?'villager-woman':'villager-1');talk(a.npc);return true}
 if(a.type.startsWith('order-parcel-'))return errand.take(Number(a.type.slice(-1)));if(a.type==='locked-home'){show('Гостевой дом','Дверь заперта.');return true}if(a.type==='storage'){storageMenu?.(a.chest);return true}if(a.type==='travel'){if(a.to==='highroad'){show('Ворота','Ворота не поддаются.');return true}if(a.to==='valden'){world.leave();sync();return true}if(a.to==='abbey'&&!['c4_braziers','c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage)){show('Чёрные мостки','Ворота не поддаются.');return true}if(a.to==='aerie'&&!['c4_dragon','c4_return','c4_done'].includes(state.stage)){show('Тропа к гнезду','Ворота не поддаются.');return true}world.resetCombat();world.enter(a.to,travelPose('c3_'+world.mode,'c3_'+a.to));flags();close();sync();return true}
 if(a.type.startsWith('c4-chain-')){if(state.stage!=='c4_chains')return true;if(!world.clearAt(a.x,a.z,12))return show('Заколдованная цепь','Ведьмы ещё удерживают чары. Победите ближайших стражей.'),true;const i=Number(a.type.slice(-1));if(!state.chains.includes(i))state.chains.push(i);flags();sync();sound();show('Лопнувшее звено','Цепи ослаблены: '+state.chains.length+' / 3. На воде слышно, как паром ударяется о причал.');return true}
 if(a.type.startsWith('c4-brazier-')){if(state.stage!=='c4_braziers')return true;if(!world.clearAt(a.x,a.z,12))return show('Пепельная жаровня','Сначала победите ближайших прислужников.'),true;const i=Number(a.type.slice(-1));if(!state.braziers.includes(i))state.braziers.push(i);flags();sync();sound();show('Погасшее пламя','Жаровни погашены: '+state.braziers.length+' / 3. Связь с алтарём слабеет.');return true}
 if(a.type==='c4-egg'){if(state.egg){show('Алтарь',state.egg==='purify'?'Яйцо очищено. Заклятия больше нет.':'На алтаре осталась только разбитая скорлупа.');return true}if(state.stage!=='c4_egg')return show('Осквернённое яйцо','По скорлупе пробегают тёмные жилы. Сначала разберитесь с Матерью и освободите пленницу.'),true;show('Последнее яйцо','Под скорлупой шевелится живое существо. Лунная печать может очистить связь, но Пеплокрыл сохранит часть защитной силы. Разрушение лишит его подпитки — и приведёт в ярость.',[['Очистить яйцо',()=>chooseEgg('purify')],['Уничтожить скверну вместе с яйцом',()=>chooseEgg('destroy')],['Мне нужно подумать',close]]);return true}
 if(a.type==='checkpoint'){p.checkpoint={id:'c3-'+world.mode,zone:'c3_'+world.mode,position:[a.fire.x+2.2,1.7,a.fire.z]};sync();sound();show('Контрольная точка','Этот очаг станет местом возвращения.');return true}if(a.type==='chest'){lootMenu(world.openChest(a.chest));return true}if(a.type==='c4-nest'){show('Гнездо Пеплокрыла','Обугленные ветви ещё тёплые. На камнях лежат осколки старых пут.');return true}return false;
 }
 function chooseEgg(choice){state.egg=choice;advance('c4_dragon');reward(p,'c4-egg','quest',700);show('Треск скорлупы',choice==='purify'?'Тёмные жилы гаснут. Под скорлупой ровно светится тёплый огонь. Из гнезда отвечает рёв: связь разорвана, но взрослый дракон ещё обезумел от боли. Его защита уцелела; зато Матерь больше не сможет призвать к нему выводок.':'Яйцо осыпается чёрным пеплом. За скалами взрывается яростный рёв. Пеплокрыл потерял защитную связь, но на его крик слетятся пепельные дракончики.')}
 function navigation(){if(!active())return null;const z=world.mode,s=state.stage;if(z==='pass')return [3600,-258];if(z==='quarry')return [4400,-26];if(z==='siege')return [4800,-20];if(z==='fortress')return s==='c4_done'||s==='c4_return'&&countItem(slots,'ash_heart')&&countItem(slots,'moon_seal')?[4006,-77]:[4076,-170];if(!world.inside)return legacy?.mode==='city'?[2425,-214]:legacy?.mode==='road'?[2000,-230]:legacy?.mode==='inn'?[2800,-20]:legacy?.mode==='manor'?[3200,-20]:[0,-118];let dest='marsh',point=[5192,-42];if(s==='c4_chains'){const points=[[-48,-115],[48,-170],[-46,-235]],i=[0,1,2].find(i=>!state.chains.includes(i));point=i===undefined?[5192,-42]:[5200+points[i][0],points[i][1]]}else if(s==='c4_braziers'){dest='abbey';const points=[[-55,-102],[55,-145],[-20,-218]],i=[0,1,2].find(i=>!state.braziers.includes(i));point=i===undefined?[5600,-231]:[5600+points[i][0],points[i][1]]}else if(['c4_abbess','c4_prisoner','c4_egg'].includes(s)){dest='abbey';point=s==='c4_abbess'?[5600,-231]:s==='c4_prisoner'&&!countItem(slots,'moon_seal')?[5600,-231]:s==='c4_prisoner'?[5623,-237]:[5600,-247]}else if(s==='c4_return'&&!countItem(slots,'moon_seal')){dest='abbey';point=[5600,-231]}else if(s==='c4_dragon'||s==='c4_return'&&!countItem(slots,'ash_heart')){dest='aerie';point=[6000,-155]}else if(['c4_return','c4_done'].includes(s)){dest='fortress';point=[4006,-77]}if(z===dest)return point;if(z==='marsh')return dest==='fortress'?[5200,-20]:[5200,-304];if(z==='abbey')return dest==='aerie'?[5600,-278]:[5600,-20];if(z==='aerie')return [6000,-20];return [4076,-170]}
 return {begin,active,flags,tick,interact,marker,navigation,objective:()=>active()?'Пепел над водой\n'+objectives[state.stage]+(state.stage==='c4_chains'?' ('+state.chains.length+' / 3)':state.stage==='c4_braziers'?' ('+state.braziers.length+' / 3)':''):null,optional:()=>[errand.objective(),active()&&state.side==='collect'?'Голоса трясины: принесите Рейне лунную траву ('+Math.min(4,countItem(slots,'moon_herb'))+' / 4)':''].filter(Boolean).join('\n'),snapshot:()=>({...state,chains:[...state.chains],braziers:[...state.braziers]}),restore(s){state={stage:'idle',chains:[],braziers:[],egg:null,side:'idle',...s};if(active())flags()},get state(){return state}};
}
